using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;

internal static class GatheringVerification {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static byte[] Hex(string text){var b=new byte[text.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(text.Substring(i*2,2),16);return b;}
 static byte[] Bytes(params byte[][] pieces){return pieces.SelectMany(p=>p).ToArray();}
 static byte[] Var(uint value){var b=new List<byte>();do{byte n=(byte)(value&127);value>>=7;b.Add(value==0?n:(byte)(n|128));}while(value!=0);return b.ToArray();}
 static byte[] Energy(uint actor){return Bytes(Hex("008D"),Var(actor),Hex("01010364000000"));}
 static byte[] Start(uint actor,uint self){return Bytes(Hex("3836"),Var(actor),Var(self),new byte[]{1});}
 static byte[] Done(uint actor,uint self,int used){return Bytes(Hex("3A36"),Var(actor),Var(self),BitConverter.GetBytes(used),new byte[4]);}
 static byte[] Remove(uint actor){return Bytes(Hex("3536"),Var(actor),Hex("040300"));}
 static void Feed(GatheringSignal s,byte[] b,double t,string flow="test"){s.Consume(b,0,b.Length,t,flow);}
 static readonly byte[] Profile=Hex("3436F5990104008AE31600893743C7462D67C600B0D2450000000000D83D43010101DF46235FA1010000010000000000000029F0CA5C070000");
 internal static void Run(string root){
 Check(GatheringCatalogue.Entries.Count==122,"Gather-source catalogue count");Check(GatheringCatalogue.Name(1500042,"es")=="Inina"&&GatheringCatalogue.Type(1500042,"es")=="Peces y mariscos"&&GatheringCatalogue.Type(1500045,"es")=="Verdura","Controlled names/types match native UI");
 GatheringSignal.Sample node;Check(GatheringSignal.Profile(Profile,0,Profile.Length,out node)&&node.Used==1&&node.Actor==19701&&node.Template==1500042,"Captured partial profile is read without earlier interactions");for(int n=0;n<Profile.Length;n++)Check(!GatheringSignal.Profile(Profile,0,n,out node),"Truncated profile cannot become live");var invalid=(byte[])Profile.Clone();invalid[42]=4;Check(!GatheringSignal.Profile(invalid,0,invalid.Length,out node),"Reject counts outside supported three-use rule");
 var s=new GatheringSignal();s.Configure(true);double now=DpsHistory.UtcNow();Feed(s,Energy(6982),now);Feed(s,Profile,now+.1);Feed(s,Start(19701,4142),now+.2);Check(s.Read(now+.2)==null,"Other gatherers never acquire own focus");Feed(s,Start(19701,6982),now+.3);Check(s.Read(now+.3).Remaining==2,"Partially used node initializes directly at two");var attempt=Hex("318D0000F59901030000000100000100000001010068010000680100000000000000000000");Feed(s,attempt,now+.35);Check(s.Read(now+.35).Remaining==1,"Explicit later attempt ordinal repairs state after a prior cancellation without a completion frame");Feed(s,Done(19701,6982,2),now+.4);Check(s.Read(now+.4).Remaining==1,"Explicit count updates remaining uses");Feed(s,Done(19701,6982,1),now+.5);Check(s.Read(now+.5).Remaining==1,"Outdated consumed values cannot restore a use");Feed(s,Remove(19701),now+.6);Check(s.Read(now+.6)==null,"Cancellation/removal hides without completion or reward");
 Feed(s,Profile,now+.7);Feed(s,Start(19701,6982),now+.8,"other");Check(s.Read(now+.8)==null,"Cross-flow identity cannot focus resource");Feed(s,Start(19701,6982),now+.9);Check(s.Read(now+.9)!=null,"Valid own focus restored");var reused=(byte[])Profile.Clone();Buffer.BlockCopy(BitConverter.GetBytes(1500045u),0,reused,7,4);Feed(s,reused,now+.95);Check(s.Read(now+.95)==null,"Reused actor with a different resource must await new own interaction");Feed(s,Start(19701,6982),now+.96);Check(s.Read(now+.96).Template==1500045,"Reused actor can focus only its current template");Check(s.Read(now+40)==null,"Stale flow cannot leave a ghost resource");s.Reset();Check(s.Read(now+1)==null,"Transport reset clears resources");Feed(s,Energy(6982),now+1.1);Feed(s,Profile,now+1.2);Feed(s,Start(19701,6982),now+1.3);var map=new byte[48];map[0]=0x21;map[1]=0x36;Buffer.BlockCopy(BitConverter.GetBytes(1010),0,map,6,4);Feed(s,map,now+1.4);Buffer.BlockCopy(BitConverter.GetBytes(1110),0,map,6,4);Feed(s,map,now+1.5);Check(s.Read(now+1.5)==null,"Map change isolates actor reuse");
 var rng=new Random(81);for(int i=0;i<1500;i++){var b=new byte[rng.Next(2,180)];rng.NextBytes(b);b[0]=0x34;b[1]=0x36;Feed(s,b,now+2+i*.001);}s.Configure(false);Check(s.Read(now+4)==null,"Disabled receiver clears live data");
 var options=new GatheringOptions{Color="#112233",Scale=150};var json=new JavaScriptSerializer();var copy=GatheringOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{crafting=options})));Check(GatheringOptions.Same(options,copy),"Options persist independently");var history=new ConfigurationHistory();var baseline=new EnergyConfiguration{Options=new EnergyBarOptions()};history.Observe(baseline);var changed=baseline.Copy();changed.Crafting.Color="#112233";history.Observe(changed);EnergyConfiguration restored;Check(history.Undo(out restored)&&restored.Crafting.Color==baseline.Crafting.Color,"Crafting supports undo without changing other widgets");
 Directory.CreateDirectory(Path.Combine(root,"designs"));using(var painter=new GatheringPainter()){for(int n=0;n<4;n++)using(var bitmap=painter.Render(new GatheringOptions(),"es",1500045,n,false)){Check(bitmap.GetPixel(0,0).A==0,"No rectangular background/frame");bitmap.Save(Path.Combine(root,"designs","gathering-"+n+".png"));}var large=new GatheringOptions{FontSize=48,TypeSize=30,BarHeight=40,Scale=200};using(var bitmap=painter.Render(large,"es",1500042,2,false))bitmap.Save(Path.Combine(root,"designs","gathering-large.png"));}
 using(var owner=new EnergyOverlay(root,true)){var cfg=owner.Configuration;cfg.Language="es";owner.ApplyConfiguration(cfg);using(var overlay=new GatheringOverlay(owner,new GatheringSignal(),true))overlay.VerifyNative();var window=new HelperSettings(owner);try{window.VerifyCrafting(root);}finally{window.Close();}}
 File.WriteAllText(Path.Combine(root,"crafting-test.txt"),"PASS: captured partial resource profile, IDs/names/native type overrides, explicit consumption, other gatherers/flows/maps/reset/stale isolation, cancelled depletion/removal, bounded malformed parsing, persistence/undo, transparent segmented rendering, large fonts, static native cache, General lock and own Crafting category.");
 }
 internal static void Replay(string root,string first,string second){var summaries=new List<object>();foreach(string path in new[]{first,second}){var signal=new GatheringSignal();signal.Configure(true);var json=new JavaScriptSerializer();int visible=0,minimum=3;bool anyOther=false;double last=0;foreach(string line in File.ReadLines(path)){var x=json.Deserialize<Dictionary<string,object>>(line);var b=Hex((string)x["hex"]);last=Convert.ToDouble(x["ts"]);signal.Consume(b,0,b.Length,last,(string)x["stream"]);var sample=signal.Read(last);if(sample!=null){visible++;minimum=Math.Min(minimum,sample.Remaining);if(sample.Template!=1500042&&sample.Template!=1500045)anyOther=true;}}Check(visible>0,"Actual capture must display identified reapproached resource");Check(!anyOther,"Nearby harvests cannot replace controlled own resource");Check(signal.Read(last)==null,"Captured exhausted resource must disappear");Check(minimum==1,"Actual captured last charge is not replaced by guessed full state");summaries.Add(new{file=Path.GetFileName(Path.GetDirectoryName(path)),visibleFrames=visible,minimumRemaining=minimum,finalVisible=false});}File.WriteAllText(Path.Combine(root,"crafting-replay-details.json"),new JavaScriptSerializer().Serialize(summaries));File.WriteAllText(Path.Combine(root,"crafting-replay-test.txt"),"PASS: both actual incoming captures, reapproach2/1 uses, self/nearby gatherer isolation and final normal/cancelled depletion.");}
}
